insert into public.prospeccao_modelos (canal, toque, assunto, texto) values
  ('whatsapp', 1, null, E'Oi, {{pessoa}}! Tudo bem? Aqui é {{seu_nome}}, da Stark 👋\n\nConverso muito com {{nicho}}{{na_cidade}} e quase sempre ouço a mesma coisa: {{dor}}.\n\nA gente resolve isso com um sistema feito sob medida: {{ganho}}.\n\nSe isso acontece aí na {{empresa}} também, posso te mostrar em 15 minutos como ficaria? Sem compromisso.'),
  ('whatsapp', 2, null, E'Oi, {{pessoa}}! Passando de novo rapidinho 🙂\n\nSei que a rotina é corrida, então vou direto: quanto tempo por semana a equipe da {{empresa}} perde com {{dor}}?\n\nNormalmente é bem mais do que parece. Com {{ganho}}, esse tempo volta para o que dá dinheiro.\n\nTopa uma conversa de 15 minutos esta semana? Me fala o melhor dia.'),
  ('whatsapp', 3, null, E'{{pessoa}}, essa é minha última mensagem, prometo não insistir 🙏\n\nSe em algum momento {{dor}} começar a pesar na {{empresa}}, me chama aqui. Te mostro sem custo como resolver.\n\nSucesso por aí! 🚀'),
  ('email', 1, E'{{empresa}}: menos retrabalho, mais tempo', E'Olá, {{pessoa}}!\n\nSou {{seu_nome}}, da Stark. Trabalhamos com {{nicho}}{{na_cidade}} e um problema aparece em quase todas: {{dor}}.\n\nNossa solução é um sistema feito sob medida para o jeito que vocês já trabalham: {{ganho}}. Sem adaptar a empresa a um software pronto.\n\nVale 20 minutos para eu entender como isso funciona hoje na {{empresa}} e te mostrar como ficaria? Se não fizer sentido, você sai da conversa com ideias de graça.\n\nAbraço,\n{{seu_nome}}\nStark · Software sob medida'),
  ('email', 2, E'Re: {{empresa}}: menos retrabalho, mais tempo', E'Oi, {{pessoa}}, tudo bem?\n\nVolto ao meu e-mail com uma pergunta direta: quantas horas por semana a equipe da {{empresa}} gasta com {{dor}}?\n\nSomando no mês, costuma ser o salário de alguém. Com {{ganho}}, esse tempo vira atendimento e venda.\n\nMe diga um horário esta semana e eu me encaixo. São 20 minutos.\n\n{{seu_nome}}\nStark · Software sob medida'),
  ('email', 3, E'Posso encerrar por aqui?', E'Oi, {{pessoa}}!\n\nNão quero lotar sua caixa de entrada, então este é meu último e-mail.\n\nSe {{dor}} virar prioridade na {{empresa}}, é só responder esta mensagem. Te mostro sem custo como resolver.\n\nSucesso por aí!\n{{seu_nome}}\nStark · Software sob medida'),
  ('linkedin', 1, null, E'Oi, {{pessoa}}! Sou {{seu_nome}}, da Stark. Trabalho com {{nicho}} e vejo muito {{dor}}.\n\nComo vocês lidam com isso na {{empresa}} hoje?'),
  ('linkedin', 2, null, E'Oi, {{pessoa}}! Retomando: costumamos resolver isso com {{ganho}}.\n\nSe fizer sentido, te mostro em 15 minutos como ficaria na {{empresa}}. Que tal esta semana?'),
  ('linkedin', 3, null, E'{{pessoa}}, passando uma última vez. Se {{dor}} virar prioridade aí, fico à disposição por aqui. Abraço!'),
  ('instagram', 1, null, E'Oi! Aqui é {{seu_nome}}, da Stark 👋 Curti muito o trabalho da {{empresa}}.\n\nAjudamos {{nicho}} que sofrem com {{dor}}. Posso te mostrar uma ideia rápida de como resolver?'),
  ('instagram', 2, null, E'Oi de novo! Só retomando: com {{ganho}}, a rotina da {{empresa}} fica bem mais leve. Te mostro em 15 minutos, topa?'),
  ('instagram', 3, null, E'Última mensagem para não incomodar 🙂 Se um dia quiserem resolver {{dor}}, é só chamar. Sucesso!')
